def count_inversions(arr):
    """
    Count the number of inversions in an array using merge sort.
    """
    if len(arr) <= 1:
        return 0, arr

    mid = len(arr) // 2
    left_count, left_arr = count_inversions(arr[:mid])
    right_count, right_arr = count_inversions(arr[mid:])

    merged_count, merged_arr = merge_and_count(left_arr, right_arr)

    return left_count + right_count + merged_count, merged_arr

def merge_and_count(left, right):
    """
    Merge two sorted arrays and count inversions.
    """
    result = []
    inversions = 0
    i = j = 0

    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            inversions += len(left) - i
            j += 1

    result.extend(left[i:])
    result.extend(right[j:])

    return inversions, result
```

