def build_bst(sorted_array):
    """
    Build a balanced BST from a sorted array.
    """
    if not sorted_array:
        return None

    mid = len(sorted_array) // 2
    root = TreeNode(sorted_array[mid])

    root.left = build_bst(sorted_array[:mid])
    root.right = build_bst(sorted_array[mid+1:])

